<template>
  <div class="dashboard" v-loading="loading">
    <section class="heading"><div><div class="eyebrow">OVERVIEW <span>·</span> {{ dateLabel }}</div><h1>{{ greeting }}，{{ userName }}<em>.</em></h1><p>从这里掌握影院动态，让每一场好电影准时开场。</p></div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新数据</el-button></section>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="error-note" />
    <section class="banner"><div><span>影院运营 · 数据概览</span><h2>银幕之上，好戏正在发生</h2><p>{{ data.cinemaName || '影院运营工作台' }}<b>/</b>{{ data.updatedAt ? '更新于 ' + data.updatedAt : '统计数据加载后显示' }}</p></div><div class="film-art" aria-hidden="true"><strong>GO</strong><i class="el-icon-video-camera-solid"></i><small>ENJOY THE SHOW</small></div></section>
    <section class="metrics"><article v-for="card in metrics" :key="card.key"><div class="metric-top"><span>{{ card.label }}</span><i :class="card.icon" :style="{color:card.color,background:card.tint}"></i></div><div class="metric-number"><small v-if="card.money">¥</small>{{ value(card.key,card.money) }}<em>{{ card.unit }}</em></div><p>{{ card.caption }}</p></article></section>
    <div class="dashboard-grid">
      <section class="panel"><div class="panel-title"><div><h3>近 7 日订单</h3><p>按下单日期统计，包含已支付与待支付订单</p></div><span class="tag">{{ data.scope === 'cinema' ? '本影院' : '全部影院' }}</span></div><div class="chart-total"><strong>{{ ready ? weeklyTotal : '—' }}</strong><span>笔订单</span></div><div class="chart" role="img" :aria-label="'近七日订单，共' + weeklyTotal + '笔'"><div class="column" v-for="day in weekly" :key="day.day"><span>{{ ready ? day.count : '—' }}</span><div class="track"><div :style="{height:ready ? (day.count/weeklyMax*100)+'%' : '0%'}"></div></div><small>{{ day.label }}</small></div></div></section>
      <section class="panel"><div class="panel-title"><div><h3>常用入口</h3><p>直达日常运营工作</p></div><i class="el-icon-position panel-icon"></i></div><div class="shortcuts"><router-link v-for="link in shortcuts" :key="link.path" :to="link.path"><i :class="link.icon" :style="{color:link.color,background:link.tint}"></i><strong>{{ link.label }}</strong><span>{{ link.desc }}</span></router-link></div><div v-if="!shortcuts.length" class="empty">当前账号暂无管理菜单权限</div><div class="pending"><i class="el-icon-time"></i><span>待支付订单</span><strong>{{ value('unpaidOrders') }}</strong><router-link v-if="canVisit('/bill')" to="/bill">查看 <i class="el-icon-arrow-right"></i></router-link></div></section>
      <section class="panel sessions"><div class="panel-title"><div><h3>近期排片</h3><p>从今日起的在映场次，按日期与时间排序</p></div><router-link v-if="canVisit('/session')" to="/session" class="text-link">全部排片 <i class="el-icon-arrow-right"></i></router-link></div><el-table :data="data.upcomingSessions || []" empty-text="暂无近期排片"><el-table-column prop="movieName" label="电影" min-width="140" show-overflow-tooltip /><el-table-column label="放映时间" min-width="120"><template slot-scope="scope">{{ dateOnly(scope.row.sessionDate) }}<small class="secondary">{{ scope.row.beginTime || '待定' }}</small></template></el-table-column><el-table-column label="影院 / 影厅" min-width="140" show-overflow-tooltip><template slot-scope="scope">{{ scope.row.cinemaName }}<small class="secondary">{{ scope.row.hallName }}</small></template></el-table-column><el-table-column label="票价" width="80" align="right"><template slot-scope="scope"><strong class="price">¥{{ Number(scope.row.price).toFixed(2) }}</strong></template></el-table-column></el-table></section>
      <section class="panel"><div class="panel-title"><div><h3>影片地区分布</h3><p>全站影片库 · 数量前五名</p></div><i class="el-icon-pie-chart panel-icon"></i></div><div class="area" v-for="(area,index) in data.movieAreas || []" :key="area.name"><div><span><i :style="{background:areaColors[index]}"></i>{{ area.name }}</span><strong>{{ area.count }}<small>部</small></strong></div><div class="area-track"><span :style="{width:(Number(area.count)/areaMax*100)+'%',background:areaColors[index]}"></span></div></div><div v-if="ready && !(data.movieAreas || []).length" class="empty">暂无影片数据</div></section>
      <section class="panel movies"><div class="panel-title"><div><h3>最近入库</h3><p>影片资料与内容管理</p></div><router-link v-if="canVisit('/movie')" to="/movie" class="text-link">影片管理 <i class="el-icon-arrow-right"></i></router-link></div><div class="movie-grid"><article v-for="movie in data.recentMovies || []" :key="movie.movieId"><div class="poster"><img v-if="poster(movie.poster) && !failedPosters[movie.movieId]" :src="poster(movie.poster)" :alt="movie.name + '海报'" @error="$set(failedPosters,movie.movieId,true)"><i v-else class="el-icon-film"></i><span>{{ Number(movie.score || 0).toFixed(1) }}</span></div><h4 :title="movie.name">{{ movie.name }}</h4><p>{{ dateOnly(movie.releaseDate) }} 上映</p></article></div><div v-if="ready && !(data.recentMovies || []).length" class="empty">暂无入库影片</div></section>
    </div><footer><span>狗眼电影 · 让好电影被看见</span><span>数据以当前业务记录为准 · 北京时间</span></footer>
  </div>
</template>
<script>
import moment from 'moment'
import { checkedRequest, pictureArray } from '@/utils/adminCrud'
export default {
  name:'Welcome',
  data() {
    let login = {}
    try { login = JSON.parse(sessionStorage.getItem('loginUser')) || {} } catch(error) { /* Login guard handles invalid sessions. */ }
    const user = login.sysUser || login
    return { loading:false,ready:false,error:'',data:{},user,failedPosters:{},areaColors:['#536fef','#7b91f3','#9baef8','#bdcafb','#dce3fc'],metrics:[
      {key:'movies',label:'在库影片',unit:'部',caption:'全站影片资料总数',icon:'el-icon-film',color:'#536fef',tint:'#eef1ff'},
      {key:'cinemas',label:'运营影院',unit:'家',caption:'当前管理范围内的影院',icon:'el-icon-office-building',color:'#22a58a',tint:'#e9f8f3'},
      {key:'todaySessions',label:'今日排片',unit:'场',caption:'今日已安排的放映场次',icon:'el-icon-date',color:'#df9a36',tint:'#fff6e7'},
      {key:'todayRevenue',label:'今日已付票款',unit:'',money:true,caption:'今日已支付订单 · 按场次票价计算',icon:'el-icon-wallet',color:'#9a69d8',tint:'#f5effc'}] }
  },
  computed:{
    userName() { return this.user.userName || '管理员' },
    greeting() { const hour = Number(moment().utcOffset(480).format('H')); return hour < 12 ? '上午好' : hour < 18 ? '下午好' : '晚上好' },
    dateLabel() { return moment().utcOffset(480).format('YYYY年MM月DD日') },
    paths() { return (this.user.sysRole && this.user.sysRole.children || []).reduce((all,group) => all.concat((group.children || []).map(item => '/' + String(item.path).replace(/^\//,''))),[]) },
    shortcuts() { return [
      {path:'/movie',label:'影片管理',desc:'维护影片资料',icon:'el-icon-video-camera',color:'#536fef',tint:'#eef1ff'},
      {path:'/session',label:'排片管理',desc:'安排放映场次',icon:'el-icon-date',color:'#22a58a',tint:'#e9f8f3'},
      {path:'/cinema',label:'影院管理',desc:'管理影院信息',icon:'el-icon-office-building',color:'#df9a36',tint:'#fff6e7'},
      {path:'/bill',label:'订单管理',desc:'查询购票订单',icon:'el-icon-tickets',color:'#9a69d8',tint:'#f5effc'}].filter(item => this.canVisit(item.path)) },
    weekly() { const end = this.data.updatedAt ? moment(this.data.updatedAt.slice(0,10)) : moment().utcOffset(480); return Array.from({length:7},(_,i) => { const date = end.clone().subtract(6-i,'days'); const day = date.format('YYYY-MM-DD'); const match = (this.data.weeklyOrders || []).find(row => this.dateOnly(row.day) === day); return {day,label:date.format('MM/DD'),count:match ? Number(match.count) : 0} }) },
    weeklyMax() { return Math.max(1,...this.weekly.map(day => day.count)) },
    weeklyTotal() { return this.weekly.reduce((total,day) => total+day.count,0) },
    areaMax() { return Math.max(1,...(this.data.movieAreas || []).map(area => Number(area.count))) }
  },
  created() { this.load() },
  methods:{
    canVisit(path) { return this.paths.includes(path) },
    async load() { if(this.loading) return; this.loading=true; this.error=''; try { const response=await checkedRequest(axios.get('sysUser/dashboard')); this.data=response.data.data; this.ready=true } catch(error) { this.error='看板数据加载失败：'+(error.message || '请稍后刷新'); this.ready=false; this.data={} } finally { this.loading=false } },
    value(key,money) { if(!this.ready || !this.data.counts || this.data.counts[key] == null) return '—'; const amount=Number(this.data.counts[key]); return money ? amount.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}) : amount.toLocaleString('zh-CN') },
    dateOnly(value) { return value ? String(value).slice(0,10) : '—' },
    poster(value) { const path=pictureArray(value)[0]; return path && path.startsWith('/images/') ? this.global.base+path : '' }
  }
}
</script>
